installer-gui-script.script:
// Advisory UI only; privileged scripts repeat broader live detection.
function hasExternal() {
  var paths = ['/Applications/Tailscale.app',
    '/Library/LaunchDaemons/com.tailscale.tailscaled.plist',
    '/Library/LaunchDaemons/homebrew.mxcl.tailscale.plist',
    '/Library/LaunchDaemons/homebrew.mxcl.tailscaled.plist',
    '/var/run/tailscaled.socket'];
  for (var i = 0; i < paths.length; i++) {
    if (system.files.fileExistsAtPath(paths[i])) return true;
  }
  return false;
}
function hasManaged() {
  return system.files.fileExistsAtPath('/Library/LaunchDaemons/io.headscaleclient.tailscaled.plist');
}
